-- | Blocky, the test character: the common states, three normals, a jump
-- attack, a dash and two specials, drawn with rectangles generated by code.
--
-- Every number here was made up for this example. It is meant to exercise
-- the engine and to be read as a tutorial, not to be balanced.
module Hugen.Example.Blocky
  ( blocky,

    -- * Placeholder art
    Role (..),
    Part (..),
    blockyArt,

    -- * State numbers
    stDash,
    stJab,
    stKick,
    stLowJab,
    stAirPunch,
    stRush,
    stUppercut,
  )
where

import qualified Data.IntMap.Strict as IntMap
import Hugen.Anim
import Hugen.Box
import Hugen.Character
import Hugen.Command
import Hugen.Common
import Hugen.Expr
import Hugen.Fixed (Fx)
import Hugen.Input (Btn (..), Dir (..))

stDash, stJab, stKick, stLowJab, stAirPunch, stRush, stUppercut :: StateId
stDash = 100
stJab = 200
stKick = 210
stLowJab = 400
stAirPunch = 600
stRush = 1000
stUppercut = 1100

blocky :: Character
blocky =
  Character
    { charName = "Blocky",
      charConsts = defaultConsts,
      charCommands = commands,
      charGlobal = global,
      charStates = IntMap.fromList (commonStates defaultConsts ++ ownStates),
      charAnims = IntMap.fromList anims
    }

-- Commands --------------------------------------------------------------------

commands :: [Command]
commands =
  [ command "qcf_a" [Press Down, Press DownFwd, Press Fwd, Buttons [BtnA]],
    command "dp_b" [Press Fwd, Press Down, Press DownFwd, Buttons [BtnB]],
    (command "ff" [Press Fwd, Press Fwd]) {cmdTime = 10},
    (command "a" [Buttons [BtnA]]) {cmdTime = 1},
    (command "b" [Buttons [BtnB]]) {cmdTime = 1}
  ]

-- | State -1: commands become moves. Order is priority: specials before the
-- normals they contain.
global :: [Controller]
global =
  [ on (cmd "dp_b" .&& ctrl .&& grounded) (changeState stUppercut),
    on (cmd "qcf_a" .&& ctrl .&& grounded) (changeState stRush),
    -- a jab that connects can be canceled into the rush
    on (cmd "qcf_a" .&& stateNo .== lit stJab .&& moveContact) (changeState stRush),
    on (cmd "ff" .&& ctrl .&& standing) (changeState stDash),
    on (cmd "a" .&& ctrl .&& standing) (changeState stJab),
    on (cmd "b" .&& ctrl .&& standing) (changeState stKick),
    on (cmd "a" .&& ctrl .&& stance .== lit Crouching) (changeState stLowJab),
    on (cmd "a" .&& ctrl .&& airborne) (changeState stAirPunch)
  ]
  where
    standing = stance .== lit Standing

-- States ----------------------------------------------------------------------

ownStates :: [(StateId, StateDef)]
ownStates =
  [ (stJab, attackState Standing stJab hitDef 1 stStand),
    ( stKick,
      attackState
        Standing
        stKick
        hitDef {hdDamage = 70, hdHitStun = 18, hdHitPause = 10, hdPushback = 6}
        1
        stStand
    ),
    (stLowJab, attackState Crouching stLowJab hitDef {hdDamage = 25} 1 stCrouch),
    (stAirPunch, attackState Airborne stAirPunch hitDef {hdDamage = 50, hdHitStun = 16} 1 stJumpAir),
    ( stDash,
      (stateDef Standing Idle PhysStand)
        { sdAnim = Just stDash,
          sdCtrl = Just False,
          sdVel = Just (7, 0),
          sdControllers = [on (time .>= 14) (changeState stStand)]
        }
    ),
    ( stRush,
      (stateDef Standing Attacking PhysNone)
        { sdAnim = Just stRush,
          sdCtrl = Just False,
          sdVel = Just (0, 0),
          sdControllers =
            [ on (animElemStarts 1) (velSetX 8),
              on (animElemStarts 1) (attack hitDef {hdDamage = 90, hdHitStun = 22, hdHitPause = 12, hdPushback = 7}),
              on (animElemStarts 2 .|| moveContact) (velSetX 0),
              on (animTime .>= 0) (changeState stStand)
            ]
        }
    ),
    ( stUppercut,
      (stateDef Airborne Attacking PhysAir)
        { sdAnim = Just stUppercut,
          sdCtrl = Just False,
          sdVel = Just (1.5, -9),
          sdControllers =
            [on (time .== 0) (attack hitDef {hdDamage = 110, hdHitStun = 30, hdHitPause = 12, hdAirLift = -7, hdPushback = 2})]
        }
    )
  ]

-- Animations ------------------------------------------------------------------
--
-- Boxes are relative to the axis between the feet, facing right, y down.

standBody, crouchBody, airBody :: Box
standBody = box (-14) (-72) 14 0
crouchBody = box (-16) (-44) 16 0
airBody = box (-14) (-64) 14 (-8)

spr :: Int -> Int -> SpriteRef
spr = SpriteRef

hitFrame :: SpriteRef -> Int -> [Box] -> [Box] -> Frame
hitFrame = Frame

anims :: [(AnimId, Anim)]
anims =
  [ (anStand, anim [frame (spr 0 0) 20 [standBody], frame (spr 0 1) 20 [standBody]]),
    (anWalk, anim [frame (spr 20 n) 8 [standBody] | n <- [0 .. 3]]),
    (anCrouch, anim [frame (spr 11 0) (-1) [crouchBody]]),
    (anJumpStart, anim [frame (spr 40 0) (-1) [crouchBody]]),
    (anJumpAir, anim [frame (spr 41 0) (-1) [airBody]]),
    (anLand, anim [frame (spr 47 0) (-1) [crouchBody]]),
    (anHit, anim [frame (spr 5000 0) (-1) [box (-16) (-70) 12 0]]),
    (anHitAir, anim [frame (spr 5030 0) (-1) [airBody]]),
    (stDash, anim [frame (spr 100 0) (-1) [standBody]]),
    ( stJab,
      anim
        [ frame (spr 200 0) 3 [standBody],
          hitFrame (spr 200 1) 3 [standBody, armBox 44] [box 26 (-62) 48 (-50)],
          frame (spr 200 0) 7 [standBody]
        ]
    ),
    ( stKick,
      anim
        [ frame (spr 210 0) 6 [standBody],
          hitFrame (spr 210 1) 4 [standBody, legBox] [box 30 (-44) 58 (-30)],
          frame (spr 210 0) 14 [standBody]
        ]
    ),
    ( stLowJab,
      anim
        [ frame (spr 400 0) 3 [crouchBody],
          hitFrame (spr 400 1) 3 [crouchBody] [box 24 (-36) 46 (-24)],
          frame (spr 400 0) 8 [crouchBody]
        ]
    ),
    ( stAirPunch,
      anim
        [ frame (spr 600 0) 4 [airBody],
          hitFrame (spr 600 1) 8 [airBody] [box 12 (-24) 40 0],
          frame (spr 600 0) (-1) [airBody]
        ]
    ),
    ( stRush,
      anim
        [ frame (spr 1000 0) 8 [standBody],
          hitFrame (spr 1000 1) 12 [standBody] [box 20 (-60) 50 (-46)],
          frame (spr 1000 0) 16 [standBody]
        ]
    ),
    ( stUppercut,
      anim
        [hitFrame (spr 1100 0) (-1) [airBody] [box 4 (-96) 30 (-40)]]
    )
  ]
  where
    armBox :: Fx -> Box
    armBox reach = box 10 (-60) reach (-52)
    legBox = box 10 (-42) 40 (-32)

-- Placeholder art -------------------------------------------------------------

-- | How the shell should color a part.
data Role = Head | Torso | Limb
  deriving (Eq, Ord, Show, Enum, Bounded)

data Part = Part
  { partRole :: Role,
    partBox :: Box
  }
  deriving (Eq, Show)

-- | The rectangles that draw each sprite, facing right, relative to the
-- axis. The shell mirrors and colors them.
blockyArt :: SpriteRef -> [Part]
blockyArt (SpriteRef g i) = case (g, i) of
  (0, 0) -> standing 0
  (0, 1) -> standing 2
  (20, n) -> walking n
  (11, _) -> crouching []
  (40, _) -> crouching []
  (47, _) -> crouching []
  (41, _) -> air []
  (5000, _) -> recoil
  (5030, _) -> air [Part Limb (box (-26) (-50) (-12) (-40))]
  (100, _) -> leaning 6 []
  (200, 1) -> standing 0 ++ [Part Limb (box 10 (-60) 48 (-50))]
  (210, 1) -> standingLegs [Part Limb (box 6 (-44) 58 (-32)), Part Limb (box (-10) (-30) 0 0)]
  (400, 1) -> crouching [Part Limb (box 10 (-36) 46 (-26))]
  (600, 1) -> air [Part Limb (box 8 (-26) 40 (-12))]
  (1000, 1) -> leaning 10 [Part Limb (box 14 (-60) 50 (-48))]
  (1100, _) -> air [Part Limb (box 6 (-96) 18 (-56))]
  (_, _) -> standing 0
  where
    head' dy dx = Part Head (box (-10 + dx) (-90 + dy) (10 + dx) (-72 + dy))
    torso dy = Part Torso (box (-14) (-72 + dy) 14 (-34))
    legs = [Part Limb (box (-12) (-34) (-2) 0), Part Limb (box 2 (-34) 12 0)]
    standing dy = [head' dy 0, torso dy, Part Limb (box (-4) (-66 + dy) 8 (-44))] ++ legs
    standingLegs extra = [head' 0 0, torso 0, Part Limb (box 2 (-34) 12 0)] ++ extra
    walking n =
      let s = if even n then 4 else -4
       in [ head' 0 0,
            torso 0,
            Part Limb (box (-12 + s) (-34) (-2 + s) 0),
            Part Limb (box (2 - s) (-34) (12 - s) 0)
          ]
    crouching extra =
      [ head' 30 4,
        Part Torso (box (-16) (-44) 16 (-14)),
        Part Limb (box (-16) (-14) 16 0)
      ]
        ++ extra
    air extra =
      [ head' 8 0,
        Part Torso (box (-14) (-64) 14 (-30)),
        Part Limb (box (-12) (-30) 12 (-12))
      ]
        ++ extra
    leaning dx extra = [head' 4 dx, Part Torso (box (-12) (-68) 16 (-34))] ++ legs ++ extra
    recoil = [head' 4 (-8), Part Torso (box (-18) (-70) 10 (-34))] ++ legs
